  final int _chunkRecords;
  final int _chunkBytes;

  /// While true, [_evictToBound] is a no-op — set for the duration of a
  /// [growOlderUntil] boundary walk so the newest side (the resume's
  /// tail anchor) cannot slide out mid-walk.
  bool _suspendEviction = false;

  final FileSystem _fs;
  final String _filePath;
  final SessionChunkReader _reader;

  /// Transient-ENOENT retry wiring (issue #427) for the disk appends;
  /// the reader-side page-ins stay outside the retry window.
  final SessionIoRetryConfig _ioRetry;

  final List<SessionRecord> _entries = [];

  /// File-order start offsets aligned with [_entries].
  final List<int> _offsets = [];

  /// File-order END offsets aligned with [_entries] (half-open spans
