      session: _session!,
      state: _agent.state,
      window: _effectiveContextWindow,
      settings: _effectiveCompactionSettings,
      sources: AutoCompactorSources(
        smolStream: smol?.stream,
        smolModel: smol?.model,
        mainStream: _streamFunction,
        mainModel: _agent.state.model,
