  Future<Session> _loadSession(SessionMetadata metadata) async {
    final bootSw = Stopwatch()..start();
    void stage(String name) => _logDiagnostic(
      'boot_stage $name ms=${bootSw.elapsedMilliseconds} sid=${metadata.id}',
    );
