import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:test/test.dart';

MessageRecord msg(String id, String? parent, String text) => MessageRecord(
  id: id,
  parentId: parent,
  timestamp: DateTime.utc(2026),
  message: UserMessage.text(text),
);

void main() {
  test('mirror check: branch WITH compaction record + kept-middle', () {
    final branch = [
      msg('e0', null, 'x' * 40000), // 10k tok — summarized (dropped)
      msg('e1', 'e0', 'y' * 40000), // 10k tok — KEPT-MIDDLE (firstKept)
      CompactionRecord(
        id: 'c0',
        parentId: 'e1',
        timestamp: DateTime.utc(2026),
        summary: 's' * 200, // 50 tok
        firstKeptEntryId: 'e1',
        tokensBefore: 99999,
      ),
      msg('e2', 'c0', 'a' * 400), // 100 tok
      msg('e3', 'e2', 'b' * 400), // 100 tok
    ];
    final forward = estimateProjectedBranchTokens(branch);
    final cut = projectedBranchBudgetCut(branch, forward);
    // If the backward fold were an exact mirror, cut for budget == forward
    // would be null (whole branch fits exactly).
    // ignore: avoid_print
    print('forward=$forward cutForBudget=$cut');
    expect(cut, isNull, reason: 'exact mirror ⇒ budget==forward fits');
  });

  test('trim bound: cut result can exceed the budget under the mirror',
      () {
    final branch = [
      msg('e0', null, 'x' * 40000), // summarized
      msg('e1', 'e0', 'y' * 40000), // kept-middle: 10k tokens
      CompactionRecord(
        id: 'c0',
        parentId: 'e1',
        timestamp: DateTime.utc(2026),
        summary: 's' * 200,
        firstKeptEntryId: 'e1',
        tokensBefore: 99999,
      ),
      msg('e2', 'c0', 'a' * 400),
      msg('e3', 'e2', 'b' * 400),
    ];
    const budget = 10150; // forward = 10250; crossing sits in kept-middle
    final cut = projectedBranchBudgetCut(branch, budget);
    // ignore: avoid_print
    print('forward=${estimateProjectedBranchTokens(branch)} cut=$cut');
    if (cut != null) {
      final kept = branch.sublist(cut);
      // ignore: avoid_print
      print(
        'kept estimate=${estimateProjectedBranchTokens(kept)} '
        '(budget=$budget)',
      );
    }
  });
